-- Append-only tables (spec 6.14: audit rows are never updated or deleted, and the role
-- has no rights to do so). Shared by the ledger tables in Phase 2.
CREATE OR REPLACE FUNCTION core.reject_mutation() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'core.% is append-only: % is not allowed', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'insufficient_privilege';
END
$$;
--> statement-breakpoint
-- Creates monthly range partitions of core.<parent> on created_at, in UTC, for `months`
-- months starting at `start_month`. Idempotent. Partitions of append-only tables get the
-- same revokes as the parent, because privileges are checked per partition when a
-- partition is addressed directly. Phase 9 schedules this ahead of time (spec 5.1).
CREATE OR REPLACE FUNCTION core.create_monthly_partitions(parent text, start_month date, months integer, append_only boolean)
  RETURNS void
  LANGUAGE plpgsql
AS $$
DECLARE
  month_start date;
  partition_name text;
BEGIN
  FOR i IN 0..months - 1 LOOP
    month_start := (date_trunc('month', start_month) + make_interval(months => i))::date;
    partition_name := parent || '_' || to_char(month_start, 'YYYYMM');
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS core.%I PARTITION OF core.%I FOR VALUES FROM (%L) TO (%L)',
      partition_name, parent,
      month_start::timestamp AT TIME ZONE 'UTC',
      (month_start + interval '1 month')::timestamp AT TIME ZONE 'UTC'
    );
    IF append_only THEN
      EXECUTE format('REVOKE UPDATE, DELETE, TRUNCATE ON core.%I FROM mulapay_core_rw', partition_name);
    END IF;
  END LOOP;
END
$$;
--> statement-breakpoint
DO $$
DECLARE
  first_month constant date := date '2025-01-01';
  months integer := (
    (extract(year FROM now() AT TIME ZONE 'UTC')::integer - 2025) * 12
    + extract(month FROM now() AT TIME ZONE 'UTC')::integer - 1
  ) + 4;
BEGIN
  PERFORM core.create_monthly_partitions('audit_logs', first_month, months, true);
END
$$;
--> statement-breakpoint
-- Safety net: a row outside the created months lands here instead of failing the audited
-- operation. Rows here block creating the matching monthly partition; Phase 9 partition
-- automation must move them first.
CREATE TABLE core.audit_logs_default PARTITION OF core.audit_logs DEFAULT;--> statement-breakpoint
REVOKE UPDATE, DELETE, TRUNCATE ON core.audit_logs, core.audit_logs_default FROM mulapay_core_rw;--> statement-breakpoint
CREATE TRIGGER audit_logs_append_only BEFORE UPDATE OR DELETE ON core.audit_logs FOR EACH ROW EXECUTE FUNCTION core.reject_mutation();--> statement-breakpoint
CREATE TRIGGER audit_logs_no_truncate BEFORE TRUNCATE ON core.audit_logs FOR EACH STATEMENT EXECUTE FUNCTION core.reject_mutation();--> statement-breakpoint
