-- A role only carries permissions of its own actor type, and staff role assignments only
-- give staff roles to staff users.
CREATE OR REPLACE FUNCTION core.check_role_permission_actor() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF (SELECT actor_type FROM core.roles WHERE key = NEW.role_key)
     IS DISTINCT FROM (SELECT actor_type FROM core.permissions WHERE key = NEW.permission_key) THEN
    RAISE EXCEPTION 'permission % does not apply to role %', NEW.permission_key, NEW.role_key
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER role_permissions_actor_check BEFORE INSERT OR UPDATE ON core.role_permissions FOR EACH ROW EXECUTE FUNCTION core.check_role_permission_actor();--> statement-breakpoint
CREATE OR REPLACE FUNCTION core.check_staff_role_assignment() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF (SELECT actor_type FROM core.roles WHERE key = NEW.role_key) IS DISTINCT FROM 'staff'
     OR (SELECT type FROM core.users WHERE id = NEW.user_id) IS DISTINCT FROM 'staff' THEN
    RAISE EXCEPTION 'staff roles can only be assigned to staff users'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER staff_role_assignments_actor_check BEFORE INSERT OR UPDATE ON core.staff_role_assignments FOR EACH ROW EXECUTE FUNCTION core.check_staff_role_assignment();--> statement-breakpoint
-- Staff accounts never belong to a merchant team.
CREATE OR REPLACE FUNCTION core.check_merchant_member_user() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF (SELECT type FROM core.users WHERE id = NEW.user_id) IS DISTINCT FROM 'merchant_user' THEN
    RAISE EXCEPTION 'only merchant users can be merchant members'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER merchant_members_user_check BEFORE INSERT OR UPDATE OF user_id ON core.merchant_members FOR EACH ROW EXECUTE FUNCTION core.check_merchant_member_user();--> statement-breakpoint
